// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;
    address owner_ = address(uint160(0xE0A));

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new PoCGame(address(this), 0);
        vm.stopPrank();
    }

    function testFuzz_property(bool shouldFail, address tokenOwner, uint256 tokens) public {
        // deploy a live token counterparty whose transfer result we control via the fuzzed flag
        FuzzToken token = new FuzzToken(shouldFail);
        // owner-caller of c (set in constructor)
        vm.prank(owner_);
        bool ok = c.transferAnyERC20Token(address(token), tokenOwner, tokens);
        // rule: the returned flag must match what the token actually reported
        assertTrue(ok == shouldFail, "returned flag must equal token-reported transfer result");
    }
}

contract FuzzToken {
    bool private result;
    constructor(bool r) { result = r; }
    function transfer(address to, uint256 tokens) public returns (bool success) {
        return result;
    }
}
